  const common = `<div class="hub-form-field"><label for="name-${service.id}">Nombre *</label><input id="name-${service.id}" name="nombre" maxlength="80" autocomplete="name" required></div><div class="hub-form-field"><label for="whatsapp-${service.id}">WhatsApp *</label><input id="whatsapp-${service.id}" name="whatsapp" type="tel" maxlength="30" autocomplete="tel" required></div><div class="hub-form-field hub-form-field--full"><label for="email-${service.id}">Email *</label><input id="email-${service.id}" name="email" type="email" maxlength="120" autocomplete="email" required></div>`;
  let fields = "";
  if (service.id === "consultoria") fields = `<div class="hub-form-field hub-form-field--full"><label for="format-consultoria">Duración *</label><select id="format-consultoria" name="duracion" required><option value="">Selecciona</option><option>30 min · 60 € IVA incluido</option><option>60 min · 90 € IVA incluido</option></select></div><div class="hub-form-field hub-form-field--full"><label for="case-consultoria">¿Qué necesitas revisar? *</label><textarea id="case-consultoria" name="caso" maxlength="1200" required></textarea></div>`;
  if (service.id === "puesta-en-marcha-subastas") fields = `<div class="hub-form-field"><label for="platform-setup">Plataforma *</label><select id="platform-setup" name="plataforma" required><option value="">Selecciona</option><option>AUTO1</option><option>Copart</option></select></div><div class="hub-form-field"><label for="experience-setup">Experiencia *</label><select id="experience-setup" name="experiencia" required><option value="">Selecciona</option><option>Nunca la he utilizado</option><option>Ya tengo acceso</option><option>Ya he revisado lotes</option></select></div><div class="hub-form-field hub-form-field--full"><label for="goal-setup">Objetivo *</label><textarea id="goal-setup" name="objetivo" maxlength="1000" required></textarea></div>`;
  if (service.id === "primera-compra-subasta") fields = `<div class="hub-form-field"><label for="profile-auction">Perfil *</label><select id="profile-auction" name="perfil" required><option value="">Selecciona</option><option>Particular</option><option>Profesional</option></select></div><div class="hub-form-field"><label for="platform-auction">Plataforma *</label><select id="platform-auction" name="plataforma" required><option value="">Selecciona</option><option>AUTO1</option><option>Copart</option><option>No lo sé</option></select></div><div class="hub-form-field"><label for="budget-auction">Rango de presupuesto *</label><select id="budget-auction" name="presupuesto" required><option value="">Selecciona</option><option>Menos de 8.000 €</option><option>8.000–15.000 €</option><option>15.000–30.000 €</option><option>Más de 30.000 €</option></select></div><div class="hub-form-field"><label for="time-auction">Plazo *</label><select id="time-auction" name="plazo" required><option value="">Selecciona</option><option>Ya</option><option>Este mes</option><option>Entre uno y tres meses</option><option>Estoy estudiándolo</option></select></div><div class="hub-form-field hub-form-field--full"><label for="goal-auction">Objetivo y experiencia *</label><textarea id="goal-auction" name="objetivo_y_experiencia" maxlength="1200" required></textarea></div>`;
  if (service.id === "primera-importacion-contigo") fields = `<div class="hub-form-field"><label for="goal-import">Objetivo *</label><select id="goal-import" name="objetivo" required><option value="">Selecciona</option><option>Coche personal</option><option>Reventa</option><option>Empezar negocio</option><option>Profesional</option></select></div><div class="hub-form-field"><label for="budget-import">Presupuesto *</label><select id="budget-import" name="presupuesto" required><option value="">Selecciona</option><option>Menos de 5.000 €</option><option>5.000–8.000 €</option><option>8.000–15.000 €</option><option>15.000–30.000 €</option><option>Más de 30.000 €</option></select></div><div class="hub-form-field"><label for="time-import">Cuándo quieres comprar *</label><select id="time-import" name="plazo" required><option value="">Selecciona</option><option>Ya</option><option>Este mes</option><option>Entre uno y tres meses</option><option>Estoy estudiándolo</option></select></div><div class="hub-form-field"><label for="car-import">Tipo de vehículo *</label><input id="car-import" name="tipo_de_vehiculo" maxlength="120" required></div><div class="hub-form-field"><label for="country-import">País o plataforma</label><input id="country-import" name="pais_o_plataforma" maxlength="100"></div><div class="hub-form-field"><label for="candidate-import">¿Tienes candidatos?</label><select id="candidate-import" name="candidatos"><option>No todavía</option><option>Sí, uno</option><option>Sí, varios</option></select></div><div class="hub-form-field hub-form-field--full"><label for="experience-import">Experiencia y mensaje *</label><textarea id="experience-import" name="experiencia_y_mensaje" maxlength="1600" required></textarea></div>`;
